#!/usr/bin/env python3
"""Lifts DataExporter.ExportCategory from DataExporter.kt byte-for-byte.

DataImporter.kt refers to DataExporter.ExportCategory (the decision-map key). Compiling the whole
DataExporter.kt would drag the export composition root into this stand, so this extractor copies
the nested enum exactly, wrapped in a stand-local `class DataExporter` so the qualified name is
unchanged. The enum body (manifest keys and fromManifestKey) is not edited.
"""
import sys

HEADER = """\
// GENERATED by extract_export_category.py from DataExporter.kt -- do not edit.
//
// DataImporter's decision map is keyed by DataExporter.ExportCategory. Only the nested enum is
// lifted (byte-for-byte) so the import composition root does not pull in the export root.
package com.newoether.agora.data

class DataExporter {
"""

FOOTER = "}\n"


def main() -> None:
    if len(sys.argv) != 3:
        raise SystemExit("usage: extract_export_category.py <DataExporter.kt> <out.kt>")
    source_path, out_path = sys.argv[1], sys.argv[2]
    lines = open(source_path, encoding="utf-8").read().splitlines(keepends=True)

    start = None
    for i, line in enumerate(lines):
        if line.strip() == "enum class ExportCategory(val manifestKey: String) {":
            start = i
            break
    if start is None:
        raise SystemExit("error: ExportCategory declaration not found")

    depth = 0
    end = None
    for i in range(start, len(lines)):
        depth += lines[i].count("{") - lines[i].count("}")
        if depth == 0 and i > start:
            end = i
            break
    if end is None:
        raise SystemExit("error: unterminated ExportCategory")

    body = "".join(lines[start : end + 1])
    open(out_path, "w", encoding="utf-8").write(HEADER + body + FOOTER)


if __name__ == "__main__":
    main()
